fun main() {
    val n = readLine()!!.toInt()
    val x = readLine()!!.toInt()

    val swaps = arrayOf(
        intArrayOf(0, 1),
        intArrayOf(1, 2)
    )

    var pos = x
    for (i in (1..n).reversed()) {
        val swap = swaps[(i - 1) % 2]
        if (pos == swap[0]) {
            pos = swap[1]
        } else if (pos == swap[1]) {
            pos = swap[0]
        }
    }
    println(pos)
}
